import{_ as e,o as a,c as o,ag as r}from"./chunks/framework.DUTPmUpA.js";const s="/_assets/lLH62-45243b2ded.CZIkzh3p.jpg",i="/_assets/lLHek-b90cae10f2.CCoeba29.png",n="/_assets/l12Ub1w.CXa3zD3x.png",d="/_assets/pyrL292.DxYdmx2l.png",u=JSON.parse(`{"title":"Добавление Hitbox к моделям без костей","description":"","frontmatter":{"title":"Добавление Hitbox к моделям без костей","author":"Noya (updated by: Abraham Blinkin' 12.10.2023)","steamId":"76561198046984233","date":"06.12.2015"},"headers":[],"relativePath":"assets/models/adding-hitbox-to-models-without-a-bone.md","filePath":"assets/models/adding-hitbox-to-models-without-a-bone.md"}`),l={name:"assets/models/adding-hitbox-to-models-without-a-bone.md"};function b(p,t,h,m,c,g){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="добавление-hitbox-к-моделям-без-костеи" tabindex="-1">Добавление Hitbox к моделям без костей <a class="header-anchor" href="#добавление-hitbox-к-моделям-без-костеи" aria-label="Permalink to &quot;Добавление Hitbox к моделям без костей&quot;">​</a></h1><p>Если вы пробовали некоторые модели объектов Valve, вы уже заметили, что у многих из них нет хитбокса, поэтому их нельзя использовать для выбираемых юнитов.</p><p>Это очень простой процесс, который занимает не более пары минут.</p><p>В этом уроке я добавлю хитбокс к этой модели: <code>gryphon_statue001.vmdl.</code>.</p><p><img src="'+s+'" alt="img"></p><h2 id="шаг-1-экспорт-hammer-dmx" tabindex="-1">Шаг 1. Экспорт Hammer DMX <a class="header-anchor" href="#шаг-1-экспорт-hammer-dmx" aria-label="Permalink to &quot;Шаг 1. Экспорт Hammer DMX&quot;">​</a></h2><p>Откройте Hammer, создайте новую карту (File-&gt;New или CTRL+N) и перетащите модель в начало координат.</p><p><img src="'+i+'" alt="img"></p><p>Вы также можете вращать, масштабировать или перемещать его по мере необходимости.</p><p>После этого выберите модель и щелкните по ней правой кнопкой мыши. Затем в разделе <strong>Выбранные объекты</strong> нажмите <strong>Создать модель из выделенного</strong>. Сохраните в каталог <strong>Модели</strong>. Имейте в виду, что вы можете выбрать несколько сеток в окне просмотра и экспортировать их как одну модель, но их текстуры не будут экспортироваться вместе с ними должным образом.</p><h2 id="шаг-2-создаите-vmdl" tabindex="-1">Шаг 2. Создайте VMDL <a class="header-anchor" href="#шаг-2-создаите-vmdl" aria-label="Permalink to &quot;Шаг 2. Создайте VMDL&quot;">​</a></h2><p>Найдите свою новую модель в Обозревателе ресурсов и дважды щелкните ее, чтобы открыть. <img src="'+n+'" alt="img"></p><h2 id="шаг-3-загрузите-cube-fbx" tabindex="-1">Шаг 3. Загрузите Cube.fbx <a class="header-anchor" href="#шаг-3-загрузите-cube-fbx" aria-label="Permalink to &quot;Шаг 3. Загрузите Cube.fbx&quot;">​</a></h2><p>Это меш с 1 костью. <a href="/cube.fbx">Download it directly</a> и поместите файл <code>Cube.fbx</code> в каталог вашей модели.</p><p>Благодарность @Internet_Veteran</p><h2 id="шаг-4-добавьте-cube-fbx-«простую-анимацию»" tabindex="-1">Шаг 4. Добавьте <code>Cube.fbx</code> «Простую анимацию» <a class="header-anchor" href="#шаг-4-добавьте-cube-fbx-«простую-анимацию»" aria-label="Permalink to &quot;Шаг 4. Добавьте `Cube.fbx` «Простую анимацию»&quot;">​</a></h2><p>Это критическая часть. По сути, вы добавите сетку куба в новую модель. Вы можете сделать это в редакторе моделей <strong>Добавить -&gt; Добавить простые анимации...</strong> и нажать «ОК». Он попросит добавить файл fbx. Выберите <code>Cube.fbx</code>, который вы поместили в каталог своих моделей.</p><h2 id="шаг-5-добавляем-«кость»" tabindex="-1">Шаг 5. Добавляем «Кость» <a class="header-anchor" href="#шаг-5-добавляем-«кость»" aria-label="Permalink to &quot;Шаг 5. Добавляем «Кость»&quot;">​</a></h2><p>Теперь перейдите в <strong>Добавить -&gt; Кость</strong> и назовите его «кость».</p><h2 id="шаг-6-добавьте-и-настроите-«хитбокс»" tabindex="-1">Шаг 6. Добавьте и настройте «Хитбокс» <a class="header-anchor" href="#шаг-6-добавьте-и-настроите-«хитбокс»" aria-label="Permalink to &quot;Шаг 6. Добавьте и настройте «Хитбокс»&quot;">​</a></h2><p>Теперь перейдите в <strong>Добавить -&gt; Hitbox</strong> и выберите <strong>(New HitboxSet)</strong> в качестве родительского узла и нажмите «ОК». Назовите хитбокс «hitbox» и нажмите «ОК», затем выберите «bone» в качестве родительской кости для хитбокса.</p><p>Теперь используйте синие стрелки в окне просмотра, чтобы отрегулировать размер хитбокса.</p><p><img src="'+d+'" alt="img"> Наконец, перейдите в <strong>Файл -&gt; Сохранить и скомпилировать</strong>.</p><p>Вот и все! Теперь у вашей модели будет внутриигровой хитбокс.</p>',24)])])}const _=e(l,[["render",b]]);export{u as __pageData,_ as default};
